# Create a test that can interact with the alert dialog and continue to the profile
cat > /tmp/UITest.m << 'EOF'
#import <XCTest/XCTest.h>

@interface UITest : XCTestCase
@end

@implementation UITest

- (void)testFollowingButtonPress {
    XCUIApplication *app = [[XCUIApplication alloc] init];
    [app launch];

    // Wait for alert and tap Open button
    XCUIElementQuery *alerts = [app.alerts matching:[NSPredicate predicateWithFormat:@"label CONTAINS 'Open in']"];
    if ([alerts.count firstMatch]) {
        XCUIElement *openButton = [[[alerts firstMatch].buttons matching:[NSPredicate predicateWithFormat:@"label = 'Open'"]] firstMatch];
        if ([openButton exists]) {
            [openButton tap];
        }
    }
}

@end
EOF

echo "Test file created"

